const owned=[...new Set(Array.isArray(raw.inventory)?raw.inventory:[])];for(const id of owned)if(Object.hasOwn(retiredEquipmentRefunds,id))p.coins+=retiredEquipmentRefunds[id];p.inventory=[...new Set([...p.inventory,...owned.filter(id=>Object.hasOwn(ITEMS,id))])];for(const slot of ['weapon','armor','shield'])p.equipment[slot]=ownedItem(p,slot).id;
