export function trainingYield(p,k){return 1+.25*((p.trainingLevels[k]||1)-1)}
export function trainingGoalTarget(kind,stat){const base={strength:18,accuracy:16,dodge:20,block:18,crit:24}[kind]||18;return Math.ceil(base*Math.sqrt(1+Math.max(0,stat-5)/200))}
export function trainingCost(p,k){return scaleCoins(campaignCoins(p),5)}
export function buyItem(p,id){const item=ITEMS[id];if(!item)return{ok:false,message:'Unknown equipment.'};const current=ownedItem(p,item.slot);if(item.tier<=current.tier)return{ok:false,message:'You already have this upgrade or better.'};if(item.tier!==current.tier+1)return{ok:false,message:'Get the next upgrade first.'};if(item.tier>Math.min(TOTAL_BATTLES,maxCleared(p)+1))return{ok:false,message:`Clear battle ${item.tier-1} to unlock this tier.`};if(p.coins<item.cost)return{ok:false,message:'You need '+formatCoins(item.cost-p.coins)+' more.'};p.coins-=item.cost;p.inventory.push(id);p.equipment[item.slot]=id;return{ok:true,message:item.name+' upgraded!'}}
export function armoryUpgrade(p){const current=['weapon','armor','shield'].map(slot=>ownedItem(p,slot)),tier=Math.min(TOTAL_BATTLES,Math.min(...current.map(item=>item.tier))+1),items=current.filter(item=>item.tier<tier).map(item=>ITEMS[`${item.slot}_t${tier}`]);return{tier,items,cost:items.reduce((sum,item)=>sum+item.cost,0n),locked:items.length>0&&tier>Math.min(TOTAL_BATTLES,maxCleared(p)+1)}}
export function buyArmory(p){const upgrade=armoryUpgrade(p);if(!upgrade.items.length)return{ok:false,message:'Armory fully upgraded.'};if(upgrade.locked)return{ok:false,message:`Clear battle ${upgrade.tier-1} to unlock this tier.`};if(p.coins<upgrade.cost)return{ok:false,message:'You need '+formatCoins(upgrade.cost-p.coins)+' more.'};p.coins-=upgrade.cost;for(const item of upgrade.items){if(!p.inventory.includes(item.id))p.inventory.push(item.id);p.equipment[item.slot]=item.id}return{ok:true,message:`Armory tier ${upgrade.tier} equipped!`}}
export function upgradeGround(p,k){if(!STATS.includes(k))return{ok:false,message:'Unknown ground.'};if(p.trainingLevels[k]>=5)return{ok:false,message:'This ground is fully upgraded.'};const required=[0,1,7,14,21][p.trainingLevels[k]];if(p.cleared.length<required)return{ok:false,message:`Clear ${required} battles to upgrade this ground.`};const cost=trainingCost(p,k);if(p.coins<cost)return{ok:false,message:'You need '+formatCoins(cost-p.coins)+' more.'};p.coins-=cost;p.trainingLevels[k]++;return{ok:true,message:'Training yield increased by 25%.'}}
export function skillRank(p,k){if(!SKILLS[k])return 0;return clamp(whole(p.skillLevels?.[k],p.skills.includes(k)?1:0),0,10)}
export function skillEffect(p,k){const rank=skillRank(p,k),level=Math.max(1,rank),effect={cooldown:SKILLS[k]?.cooldown||0,damage:0,duration:0,tickDamage:0,guardHits:0,heal:0};if(k==='flare'){effect.damage=2.5+.1*(level-1);effect.cooldown=15-Math.floor((level-1)/3)}if(k==='bash'){effect.damage=1.2+level*.05;effect.duration=2.1;effect.stunTurns=1}if(k==='poison'){effect.tickDamage=.25+level*.015;effect.duration=8}if(k==='ward'){effect.guardHits=3+Math.floor((level-1)/3);effect.cooldown=20-.5*(level-1)}if(k==='mend')effect.heal=.2+.01*(level-1);return effect}
export function skillUpgrade(p,k){const skill=SKILLS[k];if(!skill)return{level:0,nextLevel:0,points:0,cost:0n,unlocked:false,maxed:true,requirement:'Unknown skill.'};const level=skillRank(p,k),nextLevel=Math.min(10,level+1),maxed=level>=10,points=1+Math.floor((nextLevel-1)/3),cost=nextLevel>1?scaleCoins(campaignCoins(p),2):0n,requiredBattles=Math.max(level?0:skill.unlockAfter,(nextLevel-1)*3),missingPrerequisite=!level&&skill.requires&&!skillRank(p,skill.requires);let requirement='';if(missingPrerequisite)requirement=`Learn ${SKILLS[skill.requires].name} first.`;else if(p.cleared.length<requiredBattles)requirement=`Clear ${requiredBattles} battles.`;return{level,nextLevel,points,cost,unlocked:!requirement,maxed,requirement}}
