return{gain,xp:goals*6+missions*6,hits:whole(session.hits),bestCombo:whole(session.bestCombo),goals,...bonuses,bonusXp:goals*6,missionStats,missionXp:missions*6,missions,perfectDodges:session.kind==='dodge'?whole(session.perfectDodges):0}
