const result=trainingRewards(p,session),banked=session.banked||{},goals=Math.max(0,result.goals-whole(banked.goals)),previousGoals=whole(p.trainingGoals),totalGoals=previousGoals+goals,statPoints=Math.floor(totalGoals/3)-Math.floor(previousGoals/3),skillPoints=Math.floor(totalGoals/5)-Math.floor(previousGoals/5);
