p.totalHits+=Math.max(0,result.hits-whole(banked.hits));p.bestCombo=Math.max(p.bestCombo,result.bestCombo);p.trainingMissions??={};if(session.missionNumber)p.trainingMissions[session.kind]=Math.max(1,whole(session.missionNumber,1));p.trainingProgress??={};p.trainingProgress[session.kind]=Number.isFinite(session.goalProgress)?Math.max(0,session.goalProgress):0;
