export function legacyCost(p,kind){return scaleCoins(campaignCoins(p),10)}
export function passiveCoins(p,now=Date.now()){const pending=coin(p.pendingIdleCoins);if(!p.cleared.length)return pending;const elapsed=Math.floor(clamp(now-p.lastCollection,0,259200000)),daily=scaleCoins(campaignCoins(p),35*(10+3*p.museum),1000);return pending+daily*BigInt(elapsed)/86400000n}
export function idleCollectionRemaining(p,now=Date.now()){return clamp(IDLE_COLLECTION_COOLDOWN-(now-(p.lastManualCollection??p.lastCollection??now)),0,IDLE_COLLECTION_COOLDOWN)}
export function canCollectMuseum(p,now=Date.now()){return p.cleared.length>0&&idleCollectionRemaining(p,now)===0&&passiveCoins(p,now)>0n}
export function bankIdleIncome(p,now=Date.now()){p.pendingIdleCoins=passiveCoins(p,now);p.lastCollection=now;return p.pendingIdleCoins}
export function collectMuseum(p,now=Date.now()){if(!canCollectMuseum(p,now))return 0n;const amount=passiveCoins(p,now);p.coins+=amount;p.pendingIdleCoins=0n;p.lastCollection=now;p.lastManualCollection=now;return amount}
export function upgradeLegacy(p,kind,now=Date.now()){if(!['home','museum'].includes(kind)||p[kind]>=5)return{ok:false,message:'Fully upgraded.'};const cost=legacyCost(p,kind);if(p.coins<cost)return{ok:false,message:'You need '+formatCoins(cost-p.coins)+' more.'};if(kind==='museum')bankIdleIncome(p,now);p.coins-=cost;p[kind]++;return{ok:true,message:kind==='home'?'Lodge improved. Replay rewards increased.':'Gallery expanded. Idle income increased.'}}
export function potionCost(p){return scaleCoins(campaignCoins(p),2)}
export function purchasePotion(p){const cost=potionCost(p);if(p.coins<cost)return{ok:false,message:'A tonic costs '+formatCoins(cost)+'.'};if(p.potions>=9)return{ok:false,message:'Your tonic pouch is full.'};p.coins-=cost;p.potions++;return{ok:true,message:'Skyberry tonic added to your pouch.'}}
export class Pool{constructor(size){this.items=Array.from({length:size},()=>({active:false}))}spawn(values){const item=this.items.find(x=>!x.active);if(!item)return null;Object.assign(item,values,{active:true});return item}clear(){for(const item of this.items)item.active=false}}
